rows=[]
for line in p.open(errors='replace'):
    if 'step:' not in line: continue
    line=re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', line)
    d={k:float(v) for k,v in re.findall(r'([\w@./-]+):\s*(-?[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?)',line)}
    if 'step' in d: rows.append(d)
print('rows:',len(rows))
keys=['step','val-core/taco/acc/mean@1','val-aux/taco/pass_rate/mean@1','critic/score/mean','actor/entropy','actor/grad_norm','actor/pg_loss','actor/pg_clipfrac','actor/ppo_kl','rollout_corr/kl','training/rollout_probs_diff_mean','training/rollout_actor_probs_pearson_corr','response_length/mean','response_length/clip_ratio','response/aborted_ratio','timing_s/step','timing_s/testing']
for r in rows:
    if r['step']<16 or r['step'] in [20,30,40,49,50,60,75,100,150,200,250,300,350,400]: print({k:round(r[k],6) for k in keys if k in r})
print('validation:')
for r in rows:
    if any(k.startswith('val-core/') for k in r): print({k:v for k,v in r.items() if k.startswith(('val-core/', 'val-aux/taco')) or k=='step'})
print('windows:')
for lo,hi in [(1,10),(11,25),(26,50),(51,100),(101,200),(201,400)]:
